    df = df[df['Report Type'] == 'Imposter Scams']
    if len(df) > 0:
        reports = df['# of Reports'].iloc[0]
        reports = str(reports).replace(',', '')
        reports = int(reports)
        return pd.DataFrame({'population': ['military'], 'percentage': [reports]})
    return pd.DataFrame({'population': ['military'], 'percentage': [0]})

