def process(load_military_reports) -> pd.DataFrame:
    df = load_military_reports
    df['Reports_Clean'] = df['# of Reports'].apply(lambda x: int(str(x).replace(',', '').replace('"', '').strip()) if pd.notna(x) else 0)
    total = df['Reports_Clean'].sum()
    return pd.DataFrame({'total_military_reports': [total]})

def process(load_military_reports) -> pd.DataFrame:
    df = load_military_reports
    fraud_reports = df[df['Report Type'] == 'Fraud']['# of Reports'].values
    other_reports = df[df['Report Type'] == 'Other']['# of Reports'].values

    fraud_count = 0
    other_count = 0

    if len(fraud_reports) > 0:
        fraud_count = int(str(fraud_reports[0]).replace(',', '').replace('"', '').strip())
    if len(other_reports) > 0:
        other_count = int(str(other_reports[0]).replace(',', '').replace('"', '').strip())

    total = fraud_count + other_count
    return pd.DataFrame({'total_military_reports': [total]})

